const entrada = $input.first().json;

let datos = entrada.body;

if (typeof datos === 'string') {
  datos = JSON.parse(datos);
}

if (!datos || !Array.isArray(datos.mensajes)) {
  throw new Error('No se recibió una lista de mensajes');
}

return datos.mensajes.map((mensaje, indice) => ({
  json: {
    telefono: mensaje.telefono || null,
    mensaje: mensaje.mensaje || '',
    fecha: mensaje.fecha || null,
    origen: 'HTML_V5_TXT',
    numero_mensaje: indice + 1
  }
}));

const resultados = $input.all();
const originales = $('Code in JavaScript').all();

if (resultados.length !== originales.length) {
  throw new Error('No coincide la cantidad de respuestas con los mensajes originales');
}

function generarId(telefono, fecha, mensaje) {
  const texto = JSON.stringify([
    String(telefono ?? '').trim(),
    String(fecha ?? '').trim(),
    String(mensaje ?? '').trim()
  ]);

  let hash = 2166136261;

  for (let i = 0; i < texto.length; i++) {
    hash ^= texto.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }

  return 'TXT-' + (hash >>> 0).toString(16).padStart(8, '0');
}

return resultados.map((item, indice) => {
  const original = originales[indice].json;

  try {
    let texto = item.json.output;

    // Eliminar posibles delimitadores Markdown
    if (typeof texto === 'string') {
      texto = texto.trim()
        .replace(/^```(?:json)?\s*/i, '')
        .replace(/\s*```$/, '');
    }

    const interpretacion =
      typeof texto === 'string' ? JSON.parse(texto) : texto;

    const tiposValidos = ['TOTAL', 'ADICIONAL', 'CORRECCION', 'AMBIGUO'];

    if (
      !interpretacion ||
      !tiposValidos.includes(interpretacion.tipo_registro) ||
      (
        interpretacion.milimetros !== null &&
        (
          typeof interpretacion.milimetros !== 'number' ||
          !Number.isFinite(interpretacion.milimetros) ||
          interpretacion.milimetros < 0
        )
      )
    ) {
      throw new Error('Respuesta de Gemini con valores inválidos');
    }

    return {
      json: {
        telefono: original.telefono,
        mensaje: original.mensaje,
        fecha: original.fecha,
        origen: original.origen,
        numero_mensaje: original.numero_mensaje,
        localidad: interpretacion.localidad ?? null,
        milimetros: interpretacion.milimetros ?? null,
        tipo_registro: interpretacion.tipo_registro,
        requiere_revision:
          interpretacion.requiere_revision === true ||
          interpretacion.tipo_registro !== 'TOTAL',
        validado: 'NO',
        id_registro: generarId(original.telefono, original.fecha, original.mensaje)
      }
    };

  } catch (error) {
    return {
      json: {
        telefono: original.telefono,
        mensaje: original.mensaje,
        fecha: original.fecha,
        origen: original.origen,
        numero_mensaje: original.numero_mensaje,
        localidad: null,
        milimetros: null,
        tipo_registro: 'AMBIGUO',
        requiere_revision: true,
        validado: 'NO',
        id_registro: generarId(original.telefono, original.fecha, original.mensaje),
        error_interpretacion: error.message
      }
    };
  }
});

const registrosNuevos = $('Code in JavaScript1').all()
  .map(item => item.json);

const filasExistentes = $input.all()
  .map(item => item.json);

const idsExistentes = new Set(
  filasExistentes
    .map(fila => String(fila.id_registro ?? '').trim())
    .filter(Boolean)
);

const idsDelLote = new Set();

return registrosNuevos.map(registro => {
  const id = String(registro.id_registro ?? '').trim();

  const duplicadoEnSheets = idsExistentes.has(id);
  const duplicadoEnLote = idsDelLote.has(id);

  if (id) {
    idsDelLote.add(id);
  }

  return {
    json: {
      ...registro,
      es_duplicado:
        !id || duplicadoEnSheets || duplicadoEnLote,
      estado_carga:
        !id
          ? 'REVISAR_SIN_ID'
          : duplicadoEnSheets || duplicadoEnLote
            ? 'DUPLICADO'
            : 'NUEVO'
    }
  };
});
